tool_input.command:
d=$(mktemp -d)
DATABASE_PATH="$d/t8.db" npm run --silent migrate
DATABASE_PATH="$d/t8.db" PORT=3920 node dist/main.js > /dev/null 2>&1 &
disown
sleep 2
curl -s http://127.0.0.1:3920/api-json -o /tmp/doc2.json
curl -s -o /tmp/apiui.html -w "%{http_code}\n" http://127.0.0.1:3920/api
node -e "
const doc = require('/tmp/doc2.json');
const op = doc.paths['/links'].post;
console.log('requestBody:', JSON.stringify(op.requestBody, null, 2));
console.log('201 schema:', JSON.stringify(op.responses['201'].content['application/json'].schema, null, 2));
console.log('paths:', Object.keys(doc.paths));
"
pkill -f "dist/main.js" 2>/dev/null
rm -rf "$d"
